#!/usr/bin/env node
/**
 * ui/scripts/gen-filefilter.mjs — generate the bridge-side mirror of the
 * engine's extension→category table.
 *
 * Source of truth: engine/src/core/query/cr_filefilter_data.cpp (GENERATED by
 * the engine's own scripts/gen_filefilter.py from the corpus FileFilter.xml —
 * 8 categories / 1,481 unique extensions at corpus 03ad46c). The bridge MUST
 * classify extensions exactly like the engine's category_mask (contracts/
 * type-maps.md §4), so the mirror is generated from the engine's own table
 * with the same regenerate-don't-edit discipline (docs/INTEGRATION-PLAN.md
 * §3.3), never hand-duplicated.
 *
 * Category bit values are pinned from engine/include/cr/cr_ui.h (cr_ui_query
 * category_mask: 1 image, 2 video, 3 audio, 4 document, 5 archive, 6 other,
 * 7 email, 8 bookmarks) — the C++ enum names map 1:1.
 *
 * Usage:
 *   node ui/scripts/gen-filefilter.mjs          # write src-tauri/src/bridge/filefilter.rs
 *   node ui/scripts/gen-filefilter.mjs --check  # freshness gate: exit 1 on drift
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const uiRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = join(uiRoot, '..');
const source = join(repoRoot, 'engine/src/core/query/cr_filefilter_data.cpp');
const target = join(uiRoot, 'src-tauri/src/bridge/filefilter.rs');

const cpp = readFileSync(source, 'utf8');

// Entry shape: {"ext", Category::Name} — extensions may contain letters,
// digits, '-', '_', '+' (e.g. "c++", "f4v"); a naive \w+ class loses them.
const rows = [...cpp.matchAll(/\{"([^"\s]+)",\s*Category::(\w+)\}/g)].map((m) => [m[1], m[2]]);
if (rows.length === 0) {
  console.error('gen-filefilter: no entries parsed — engine table moved?');
  process.exit(1);
}

const BITS = {
  Image: 1,
  Video: 2,
  Audio: 3,
  Document: 4,
  Archive: 5,
  Other: 6,
  Email: 7,
  Bookmarks: 8,
};
for (const [, cat] of rows) {
  if (!(cat in BITS)) {
    console.error(`gen-filefilter: unknown Category::${cat}`);
    process.exit(1);
  }
}

// ASCII-sorted, unique — byte-parity with the engine's own sorted table.
const seen = new Map();
for (const [ext, cat] of rows) seen.set(ext, BITS[cat]);
const sorted = [...seen.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

const header = `//! bridge/filefilter.rs — GENERATED by ui/scripts/gen-filefilter.mjs from
//! engine/src/core/query/cr_filefilter_data.cpp (${sorted.length} extensions).
//! DO NOT EDIT — run the generator (node ui/scripts/gen-filefilter.mjs); the
//! CI freshness gate (ui/scripts/gen-filefilter.mjs --check) fails on drift.
//!
//! Bits mirror the engine's cr_ui_query.category_mask exactly (cr_ui.h):
//! 1 image, 2 video, 3 audio, 4 document, 5 archive, 6 other, 7 email,
//! 8 bookmarks. Unknown extensions classify as Other (6) — the engine's
//! own rule (cr_query.h category_for_extension).

//! Sorted (ext, category-bit) rows; binary-searched below.
static ENTRIES: &[(&str, u8)] = &[
`;

const body = sorted.map(([ext, bit]) => `    ("${ext}", ${bit}),`).join('\n');
const footer = `
];

/// The extension→category-bit classification the engine's category_mask
/// applies (contracts/type-maps.md §4). 'ext': lowercase, no dot; unknown
/// → 6 (Other), exactly like the engine.
pub fn category_for_extension(ext: &str) -> u8 {
    if ext.is_empty() {
        return 6;
    }
    match ENTRIES.binary_search_by(|probe| probe.0.cmp(ext)) {
        Ok(i) => ENTRIES[i].1,
        Err(_) => 6, // Other — the engine's unknown-extension rule
    }
}

/// The FileCategoryId label for a category bit (bridge-side diagnostics and
/// the type-tree composition); zero bit (directories) has no label.
pub fn category_label(bit: u8) -> Option<&'static str> {
    Some(match bit {
        1 => "graphics",
        2 => "video",
        3 => "audio",
        4 => "document",
        5 => "archive",
        6 => "other",
        7 => "email",
        8 => "bookmarks",
        _ => return None,
    })
}

/// The category bit for a UI FileCategoryId label (type-maps.md §5).
pub fn category_bit(label: &str) -> u8 {
    match label {
        "graphics" => 1,
        "video" => 2,
        "audio" => 3,
        "document" => 4,
        "archive" => 5,
        "other" => 6,
        "email" => 7,
        "bookmarks" => 8,
        _ => 0,
    }
}
`;

const out = header + body + footer;
if (process.argv.includes('--check')) {
  const current = readFileSync(target, 'utf8');
  if (current !== out) {
    console.error(
      `check-filefilter: ${target} is stale — regenerate with ` +
        `'node ui/scripts/gen-filefilter.mjs' (engine table: ${sorted.length} extensions)`,
    );
    process.exit(1);
  }
  console.log(`check-filefilter: fresh (${sorted.length} extensions)`);
  process.exit(0);
}
writeFileSync(target, out);
console.log(`gen-filefilter: wrote ${target} (${sorted.length} extensions)`);
